SET NAMES utf8mb4;
-- Démonstration : photos d'ambiance des événements publiés (remplacent les illustrations générées).
-- Rejouable : seule une image de démonstration d'origine (ou l'absence d'image pour l'afterwork) est remplacée ;
-- une image envoyée par Chloé n'est jamais écrasée.
START TRANSACTION;
SET @client=(SELECT c.id FROM clients c JOIN utilisateurs u ON u.id=c.utilisateur_id WHERE u.email_normalise='alice@example.invalid');
UPDATE evenements SET image_reference='65465b9034616c0e13098b6b2bb11126a7da4f97792fb29bf36c3895f0c51e93.jpg', image_alternative='Convention : un intervenant sur une grande scène éclairée en bleu et rouge, devant une salle comble', revision=revision+1 WHERE client_id=@client AND nom='Convention annuelle Horizon' AND image_reference='600147525fe160baab01850945ae43f0fc4e6e6645e6ed43e485e4d8f611a42e.jpg';
UPDATE evenements SET image_reference='1cc4255ca8f4737c15912e92a5153c58c2979aff9051ddfb839b95fa0e750878.jpg', image_alternative='Séminaire : une intervenante au micro devant des participants assis autour de tables', revision=revision+1 WHERE client_id=@client AND nom='Séminaire de direction Horizon' AND image_reference='36c4074425ec5519ab82d6a7a66104094c92d367b001910cd07d5d48cff11ca3.jpg';
UPDATE evenements SET image_reference='cc6fca403899328c4ef1a96ca65e527abbfb7b4625031b51c9639a05bd06f0a7.jpg', image_alternative='Dîner de gala : invités souriants autour d’une table décorée de fleurs rouges et bleues', revision=revision+1 WHERE client_id=@client AND nom='Soirée des dix ans Horizon' AND image_reference='c13bdec59b19ff9d104ae7518712c85d425569e29cdf21d138f118896a17dfa7.jpg';
UPDATE evenements SET image_reference='fb32cb3c06605095b2a89676ffd8b1dce0f3fd36aa2cef44234c6c4ed69d1984.jpg', image_alternative='Journée de cohésion : une participante traverse une poutre en riant, aidée par deux collègues', revision=revision+1 WHERE client_id=@client AND nom='Journée cohésion Horizon' AND image_reference='df82faeeaa6e6781a8845d46cb687c1e6fa7a8b777592b4448512411d7d13989.jpg';
UPDATE evenements SET image_reference='638a2601d9277ad6da320691e024511ecb5feed1a90fea8e166a002b53371ba7.jpg', image_alternative='Atelier : une équipe souriante réfléchit autour d’une table couverte de notes colorées', revision=revision+1 WHERE client_id=@client AND nom='Ateliers innovation Horizon' AND image_reference='e1c25a5cd28b528637aa97db9eb102be1ecf886065db5448601b6bd0b5d7fa0a.jpg';
UPDATE evenements SET image_reference='d4c4087ff77eaf849a0b0e7ae45c0572163a0e5a4cfd126a46129d8dd6ba86de.jpg', image_alternative='Lancement : un présentateur dévoile un véhicule bâché sous les projecteurs, devant des invités qui applaudissent', revision=revision+1 WHERE client_id=@client AND nom='Lancement produit Horizon' AND image_reference='539f8e9aca14ce051d998c8ae02379922c186e4e5ca492573f08e38c63a35ed6.jpg';
UPDATE evenements SET image_reference='0a7b99c59ed96efcad62b41b37ba7bc7075ad7d0286d84a9283932b76693ac35.jpg', image_alternative='Afterwork : une invitée éclate de rire au milieu de collègues en soirée', revision=revision+1 WHERE client_id=@client AND nom='Afterwork de rentrée Horizon' AND image_reference IS NULL;
COMMIT;
